DECLARE payload jsonb:='{"before":[{"oid":"95108","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":23,"identity":"public.materials_read(p_order uuid, p_customer uuid, p_hash text)","in_scope":true,"language":"plpgsql","lf_count":23,"body_bytes":1556,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"jsonb","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"c246f44ffe7828e1017afdd005e15d83","definition_md5":"87bda8784fa2db5f284983a97a7f7762","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},{"oid":"95110","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":6,"identity":"public.materials_complete_grant(p_order uuid, p_hash text)","in_scope":true,"language":"plpgsql","lf_count":6,"body_bytes":272,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"void","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"ea0b69745aedd817d244422312074a10","definition_md5":"bb16e02e10a3cb212bfaf39575eaacc8","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":false},{"oid":"91298","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":261,"identity":"public.replace_signature_voice_source(p_order_id uuid, p_cart_item_id uuid, p_creation_id uuid, p_admin_customer_id uuid, p_expected_asset_id uuid, p_new_asset_id uuid, p_new_storage_path text, p_new_content_type text, p_new_size_bytes bigint, p_new_duration_seconds numeric, p_new_sha256 text, p_new_original_name text, p_reason text, p_authorization_reference text, p_subject_name text, p_subject_relationship text)","in_scope":true,"language":"plpgsql","lf_count":261,"body_bytes":8394,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"b9fed9faae100e60046bf11a029b18e9","definition_md5":"569d728a09de929a4c8f290ad072a586","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},{"oid":"91383","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":51,"identity":"public.invalidate_signature_voice_narration_on_source_change()","in_scope":true,"language":"plpgsql","lf_count":51,"body_bytes":1918,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"trigger","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"f514c1be28184b16e478d60ca8435fd0","definition_md5":"5058afcaeefb00176b4c8b7aaee5b39a","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},{"oid":"91457","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":22,"identity":"public.lock_signature_voice_narration_creation()","in_scope":true,"language":"plpgsql","lf_count":22,"body_bytes":781,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"trigger","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"c08a5bfb07b79e1ae9264ad0f86869e3","definition_md5":"958522b1cf5513dbfbe3c34eb2ecdf41","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},{"oid":"91172","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":63,"identity":"public.enqueue_expired_unbound_voice_assets(p_cutoff timestamp with time zone, p_limit integer)","in_scope":true,"language":"plpgsql","lf_count":63,"body_bytes":1690,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"integer","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"708722d3582a825658294d81ad12c9da","definition_md5":"0e7005b37d6e29735a56aad31b5b356e","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},{"oid":"91165","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":73,"identity":"public.delete_owned_unbound_user_asset(p_asset_id uuid, p_owner_type text, p_anon_session_id uuid, p_customer_id uuid)","in_scope":true,"language":"plpgsql","lf_count":73,"body_bytes":2165,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"06c3c8bf256f65860b67f63646afdcf1","definition_md5":"8f683f1c2ea7793c41eaeb33437d0218","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},{"oid":"91173","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":33,"identity":"public.claim_user_asset_cleanup(p_limit integer)","in_scope":true,"language":"plpgsql","lf_count":33,"body_bytes":987,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"cc583d1f7e061a5ef21b46a4f2217578","definition_md5":"8fa22b45c95cae7949cf9d09061209d4","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},{"oid":"95112","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":35,"identity":"public.materials_bind_voice(p_order uuid, p_item uuid, p_customer uuid, p_hash text, p_asset uuid, p_authorization uuid)","in_scope":true,"language":"plpgsql","lf_count":35,"body_bytes":2524,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"void","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"ff9ed30fc1dcae9aa3c27bc5fa491487","definition_md5":"935cae0798167d28e09151ad3ac70bd6","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true}],"patches":[{"identity":"public.materials_read(p_order uuid, p_customer uuid, p_hash text)","before":{"oid":"95108","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":23,"identity":"public.materials_read(p_order uuid, p_customer uuid, p_hash text)","in_scope":true,"language":"plpgsql","lf_count":23,"body_bytes":1556,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"jsonb","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"c246f44ffe7828e1017afdd005e15d83","definition_md5":"87bda8784fa2db5f284983a97a7f7762","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},"body":"\nDECLARE result jsonb;\nBEGIN\n  PERFORM public.materials_assert_access(p_order,p_customer,p_hash);\n  IF EXISTS(SELECT 1 FROM public.cart_items i LEFT JOIN public.cart_item_dedications d\n    ON d.cart_item_id=i.cart_item_id WHERE i.order_id=p_order AND i.status::text=''ordered''\n      AND d.cart_item_id IS NULL) THEN RAISE EXCEPTION ''materials_lines_unavailable''; END IF;\n  IF EXISTS(SELECT 1 FROM public.cart_items i LEFT JOIN public.order_line_voice v ON v.cart_item_id=i.cart_item_id\n    WHERE i.order_id=p_order AND i.status::text=''ordered'' AND i.package_type::text=''supreme'' AND v.cart_item_id IS NULL)\n    THEN RAISE EXCEPTION ''materials_lines_unavailable''; END IF;\n  SELECT jsonb_build_object(''order_id'',o.order_id,''dedication_deadline'',o.paid_at+interval ''48 hours'',\n    ''items'',coalesce(jsonb_agg(jsonb_build_object(''cart_item_id'',i.cart_item_id,\n      ''creation_id'',i.creation_id,''template_id'',c.template_id,''package_type'',i.package_type,\n      ''dedication'',jsonb_build_object(''body'',d.body,''decision'',d.decision,''revision'',d.revision),\n      ''can_edit_dedication'',clock_timestamp()<o.paid_at+interval ''48 hours'',\n      ''voice_ready'',v.voice_asset_id IS NOT NULL,\n      ''voice_asset_id'',v.voice_asset_id,''voice_revision'',v.revision,''voice_uploaded_at'',a.created_at,\n      ''voice_replace_until'',o.paid_at+interval ''48 hours'',\n      ''can_replace_voice'',i.package_type=''supreme'' AND v.voice_asset_id IS NOT NULL AND o.shipped_at IS NULL\n        AND clock_timestamp()<o.paid_at+interval ''48 hours'',\n      ''can_submit_voice'',i.package_type=''supreme'' AND o.shipped_at IS NULL\n        AND (v.voice_asset_id IS NULL OR clock_timestamp()<o.paid_at+interval ''48 hours''))\n      ORDER BY i.cart_item_id),''[]''::jsonb)) INTO result\n  FROM public.orders o JOIN public.cart_items i ON i.order_id=o.order_id AND i.status::text=''ordered''\n  JOIN public.creations c ON c.creation_id=i.creation_id\n  JOIN public.cart_item_dedications d ON d.cart_item_id=i.cart_item_id\n  LEFT JOIN public.order_line_voice v ON v.cart_item_id=i.cart_item_id\n  LEFT JOIN public.user_assets a ON a.asset_id=v.voice_asset_id\n  WHERE o.order_id=p_order AND (p_hash IS NULL OR i.cart_item_id=ANY(\n    (SELECT item_ids FROM public.order_material_grants WHERE token_hash=p_hash)::uuid[]))\n  GROUP BY o.order_id,o.paid_at;\n  IF result IS NULL THEN RAISE EXCEPTION ''materials_lines_unavailable''; END IF;\n  RETURN result;\nEND ","after_md5":"77de24e590776e6497a6ca09357e72f1"},{"identity":"public.materials_complete_grant(p_order uuid, p_hash text)","before":{"oid":"95110","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":6,"identity":"public.materials_complete_grant(p_order uuid, p_hash text)","in_scope":true,"language":"plpgsql","lf_count":6,"body_bytes":272,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"void","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"ea0b69745aedd817d244422312074a10","definition_md5":"bb16e02e10a3cb212bfaf39575eaacc8","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":false},"body":"\nBEGIN\n  -- Completion is acknowledgement, never grant revocation or GET mutation.\n  PERFORM public.materials_assert_access(p_order,NULL,p_hash);\nEND\n","after_md5":"c8531db9bb8a45d7dd042a23cc8ae8d1"},{"identity":"public.replace_signature_voice_source(p_order_id uuid, p_cart_item_id uuid, p_creation_id uuid, p_admin_customer_id uuid, p_expected_asset_id uuid, p_new_asset_id uuid, p_new_storage_path text, p_new_content_type text, p_new_size_bytes bigint, p_new_duration_seconds numeric, p_new_sha256 text, p_new_original_name text, p_reason text, p_authorization_reference text, p_subject_name text, p_subject_relationship text)","before":{"oid":"91298","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":261,"identity":"public.replace_signature_voice_source(p_order_id uuid, p_cart_item_id uuid, p_creation_id uuid, p_admin_customer_id uuid, p_expected_asset_id uuid, p_new_asset_id uuid, p_new_storage_path text, p_new_content_type text, p_new_size_bytes bigint, p_new_duration_seconds numeric, p_new_sha256 text, p_new_original_name text, p_reason text, p_authorization_reference text, p_subject_name text, p_subject_relationship text)","in_scope":true,"language":"plpgsql","lf_count":261,"body_bytes":8394,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"b9fed9faae100e60046bf11a029b18e9","definition_md5":"569d728a09de929a4c8f290ad072a586","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},"body":"\ndeclare\n  v_creation public.order_line_voice%rowtype;\n  v_old_asset public.user_assets%rowtype;\n  v_state public.signature_voice_production_states%rowtype;\n  v_upload public.signature_voice_replacement_uploads%rowtype;\n  v_now timestamptz := clock_timestamp();\n  v_reason text := nullif(btrim(coalesce(p_reason, '''')), '''');\n  v_authorization_reference text := nullif(btrim(coalesce(p_authorization_reference, '''')), '''');\n  v_subject_name text := nullif(btrim(coalesce(p_subject_name, '''')), '''');\n  v_other_binding_exists boolean := false;\n  v_authorization_id uuid;\nbegin\n  PERFORM 1 FROM public.orders WHERE order_id=p_order_id FOR UPDATE;\n  perform pg_advisory_xact_lock(hashtextextended(p_cart_item_id::text,0));\n  if not exists (\n    select 1\n    from public.customers admin_customer\n    where admin_customer.customer_id = p_admin_customer_id\n      and admin_customer.role::text = ''admin''\n  ) then\n    raise exception ''admin_access_required'' using errcode = ''42501'';\n  end if;\n  if v_reason is null or char_length(v_reason) > 1000 then\n    raise exception ''signature_voice_replacement_reason_required'' using errcode = ''22023'';\n  end if;\n  if v_authorization_reference is null or char_length(v_authorization_reference) > 500 then\n    raise exception ''signature_voice_authorization_reference_required'' using errcode = ''22023'';\n  end if;\n  if v_subject_name is null or char_length(v_subject_name) > 120\n    or p_subject_relationship not in (\n      ''self'',\n      ''parent_or_guardian'',\n      ''family_member'',\n      ''other_authorized_adult''\n    ) then\n    raise exception ''signature_voice_subject_declaration_invalid'' using errcode = ''22023'';\n  end if;\n  if nullif(btrim(coalesce(p_new_storage_path, '''')), '''') is null\n    or p_new_content_type not in (\n      ''audio/webm'',\n      ''audio/mp4'',\n      ''audio/mpeg'',\n      ''audio/wav'',\n      ''audio/x-wav'',\n      ''audio/ogg'',\n      ''audio/x-m4a''\n    )\n    or p_new_size_bytes <= 0\n    or p_new_size_bytes > 15728640\n    or p_new_duration_seconds < 10\n    or p_new_duration_seconds > 20\n    or p_new_sha256 !~ ''^[0-9a-f]{64}$'' then\n    raise exception ''signature_voice_replacement_file_invalid'' using errcode = ''22023'';\n  end if;\n\n  select creation.*\n  into v_creation\n  from public.orders purchase_order\n  join public.cart_items item\n    on item.order_id = purchase_order.order_id\n  join public.order_line_voice creation\n    on creation.cart_item_id = item.cart_item_id and creation.creation_id = item.creation_id\n  where purchase_order.order_id = p_order_id\n    and purchase_order.payment_id is not null\n    and item.cart_item_id = p_cart_item_id\n    and item.status::text = ''ordered''\n    and lower(coalesce(item.package_type::text, '''')) = ''supreme''\n    and creation.creation_id = p_creation_id\n  for update of creation;\n\n  if not found then\n    raise exception ''signature_voice_order_item_not_found'' using errcode = ''P0002'';\n  end if;\n  if v_creation.voice_asset_id is distinct from p_expected_asset_id then\n    raise exception ''signature_voice_source_changed'' using errcode = ''PT409'';\n  end if;\n\n  select upload.*\n  into v_upload\n  from public.signature_voice_replacement_uploads upload\n  where upload.asset_id = p_new_asset_id\n  for update;\n  if not found\n    or v_upload.upload_status <> ''pending''\n    or v_upload.expires_at <= v_now\n    or v_upload.order_id is distinct from p_order_id\n    or v_upload.cart_item_id is distinct from p_cart_item_id\n    or v_upload.creation_id is distinct from p_creation_id\n    or v_upload.expected_asset_id is distinct from p_expected_asset_id\n    or v_upload.source_revision is distinct from v_creation.revision\n    or v_upload.admin_customer_id is distinct from p_admin_customer_id\n    or v_upload.storage_path is distinct from p_new_storage_path\n    or v_upload.original_filename is distinct from p_new_original_name\n    or v_upload.content_type is distinct from p_new_content_type\n    or v_upload.size_bytes is distinct from p_new_size_bytes then\n    raise exception ''signature_voice_replacement_upload_invalid'' using errcode = ''23514'';\n  end if;\n\n  select asset.*\n  into v_old_asset\n  from public.user_assets asset\n  where asset.asset_id = v_creation.voice_asset_id\n  for update;\n  if not found then\n    raise exception ''signature_voice_source_not_found'' using errcode = ''P0002'';\n  end if;\n\n  insert into public.user_assets (\n    asset_id,\n    owner_type,\n    anon_session_id,\n    customer_id,\n    asset_type,\n    storage_path,\n    metadata\n  )\n  values (\n    p_new_asset_id,\n    v_creation.owner_type,\n    v_creation.anon_session_id,\n    v_creation.customer_id,\n    ''voice_sample'',\n    p_new_storage_path,\n    jsonb_build_object(\n      ''role'', ''voice'',\n      ''created_for'', ''signature_voice_replacement'',\n      ''source'', ''admin_replacement'',\n      ''original_name'', left(coalesce(p_new_original_name, ''''), 255),\n      ''content_type'', p_new_content_type,\n      ''size_bytes'', p_new_size_bytes,\n      ''duration_seconds'', p_new_duration_seconds,\n      ''sha256'', p_new_sha256,\n      ''replaced_by'', p_admin_customer_id,\n      ''replaced_at'', v_now\n    )\n  );\n\n  INSERT INTO public.order_line_voice_admin_authorizations(order_id,cart_item_id,asset_id,customer_id,\n    admin_customer_id,evidence_reference,declared_at,subject_name,subject_relationship)\n  VALUES(p_order_id,p_cart_item_id,p_new_asset_id,v_creation.customer_id,p_admin_customer_id,\n    v_authorization_reference,v_now,v_subject_name,p_subject_relationship)\n  RETURNING authorization_id INTO v_authorization_id;\n  update public.order_line_voice creation\n  set voice_asset_id = p_new_asset_id,\n      voice_sample_duration_seconds = p_new_duration_seconds,\n      voice_subject_name = v_subject_name,\n      voice_subject_relationship = p_subject_relationship,\n      binding_origin=''admin_replacement'',voice_capture_authorization_id=NULL,\n      voice_admin_authorization_id=v_authorization_id,voice_consent_version=''signature-voice-admin-declaration-v1'',\n      voice_speaker_kind=''admin_declared'',voice_consent_accepted_at=NULL,\n      voice_bound_at = v_now,\n      updated_at = v_now\n  where creation.cart_item_id = p_cart_item_id and creation.creation_id = p_creation_id RETURNING * INTO v_creation;\n\n  insert into public.signature_voice_production_states (\n    cart_item_id, creation_id,\n    source_revision,\n    technical_status,\n    adult_declaration_status,\n    updated_at\n  )\n  values (\n    p_cart_item_id, p_creation_id,\n    v_creation.revision,\n    ''pending'',\n    ''pending'',\n    v_now\n  )\n  on conflict (cart_item_id) do update\n  set source_revision = excluded.source_revision,\n      technical_status = ''pending'',\n      technical_reason = null,\n      technical_reviewed_by = null,\n      technical_reviewed_at = null,\n      adult_declaration_status = ''pending'',\n      adult_declaration_reason = null,\n      adult_declaration_reviewed_by = null,\n      adult_declaration_reviewed_at = null,\n      updated_at = v_now\n  returning * into v_state;\n\n  insert into public.signature_voice_audit_events (\n    order_id,\n    cart_item_id,\n    creation_id,\n    source_asset_id,\n    actor_customer_id,\n    event_type,\n    reason,\n    authorization_reference,\n    declared_subject_name,\n    declared_subject_relationship,\n    metadata\n  )\n  values (\n    p_order_id,\n    p_cart_item_id,\n    p_creation_id,\n    p_new_asset_id,\n    p_admin_customer_id,\n    ''source_replaced'',\n    v_reason,\n    v_authorization_reference,\n    v_subject_name,\n    p_subject_relationship,\n    jsonb_build_object(\n      ''old_asset_id'', v_old_asset.asset_id,\n      ''new_asset_id'', p_new_asset_id,\n      ''source_revision'', v_state.source_revision,\n      ''size_bytes'', p_new_size_bytes,\n      ''duration_seconds'', p_new_duration_seconds,\n      ''sha256'', p_new_sha256\n    )\n  );\n\n  update public.signature_voice_replacement_uploads upload\n  set upload_status = ''consumed'',\n      consumed_at = v_now,\n      updated_at = v_now\n  where upload.asset_id = p_new_asset_id;\n\n  PERFORM public.enqueue_voice_superseded_file(p_order_id,p_cart_item_id,v_old_asset.asset_id,\n    v_old_asset.asset_type::text,v_old_asset.storage_path,''admin_replacement'');\n\n  return query\n  select\n    p_creation_id,\n    p_new_asset_id,\n    v_old_asset.asset_id,\n    v_state.source_revision,\n    v_state.updated_at;\nend;\n","after_md5":"f1d96c9a88eae517377e9272baf0fb44"},{"identity":"public.invalidate_signature_voice_narration_on_source_change()","before":{"oid":"91383","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":51,"identity":"public.invalidate_signature_voice_narration_on_source_change()","in_scope":true,"language":"plpgsql","lf_count":51,"body_bytes":1918,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"trigger","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"f514c1be28184b16e478d60ca8435fd0","definition_md5":"5058afcaeefb00176b4c8b7aaee5b39a","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},"body":"\ndeclare\n  v_narration_retention_until timestamptz := now() + interval ''30 days'';\nbegin\n  if old.voice_asset_id is null\n    or old.voice_asset_id is not distinct from new.voice_asset_id then\n    return new;\n  end if;\n\n  INSERT INTO public.signature_voice_production_states(cart_item_id,creation_id,source_revision,narration_outdated)\n  VALUES(NEW.cart_item_id,NEW.creation_id,NEW.revision,\n    EXISTS(SELECT 1 FROM public.signature_voice_narration_tracks WHERE cart_item_id=NEW.cart_item_id)\n    OR EXISTS(SELECT 1 FROM public.signature_voice_hardware_attestations WHERE cart_item_id=NEW.cart_item_id))\n  ON CONFLICT(cart_item_id) DO UPDATE SET source_revision=NEW.revision,\n    narration_outdated=public.signature_voice_production_states.narration_outdated OR EXCLUDED.narration_outdated,\n    technical_status=''pending'',technical_reason=NULL,technical_reviewed_by=NULL,technical_reviewed_at=NULL,\n    adult_declaration_status=''pending'',adult_declaration_reason=NULL,adult_declaration_reviewed_by=NULL,\n    adult_declaration_reviewed_at=NULL,updated_at=clock_timestamp();\n  DELETE FROM public.signature_voice_hardware_attestations WHERE cart_item_id=NEW.cart_item_id;\n  PERFORM public.enqueue_voice_superseded_file(NEW.order_id,NEW.cart_item_id,upload.asset_id,\n    ''signature_voice_narration'',upload.storage_path,CASE WHEN NEW.binding_origin=''post_payment'' THEN ''customer_replacement'' ELSE ''admin_replacement'' END)\n  FROM public.signature_voice_narration_uploads upload WHERE upload.cart_item_id=OLD.cart_item_id;\n  PERFORM public.enqueue_voice_superseded_file(NEW.order_id,NEW.cart_item_id,track.asset_id,\n    ''signature_voice_narration'',track.storage_path,CASE WHEN NEW.binding_origin=''post_payment'' THEN ''customer_replacement'' ELSE ''admin_replacement'' END)\n  FROM public.signature_voice_narration_tracks track WHERE track.cart_item_id=OLD.cart_item_id;\n\n  delete from public.signature_voice_narration_uploads upload\n  where upload.cart_item_id = old.cart_item_id;\n  delete from public.signature_voice_narration_tracks track\n  where track.cart_item_id = old.cart_item_id;\n\n  return new;\nend;\n","after_md5":"ec8c723d8f7b1425a2643c316dedaeab"},{"identity":"public.lock_signature_voice_narration_creation()","before":{"oid":"91457","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":22,"identity":"public.lock_signature_voice_narration_creation()","in_scope":true,"language":"plpgsql","lf_count":22,"body_bytes":781,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"trigger","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"c08a5bfb07b79e1ae9264ad0f86869e3","definition_md5":"958522b1cf5513dbfbe3c34eb2ecdf41","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},"body":"\ndeclare\n  v_line_id uuid;\nbegin\n  IF TG_OP=''UPDATE'' AND OLD.cart_item_id IS NULL AND NEW.cart_item_id IS NOT NULL\n    AND (to_jsonb(NEW)-''cart_item_id'')=(to_jsonb(OLD)-''cart_item_id'') THEN RETURN NEW; END IF;\n  v_line_id := case when tg_op = ''DELETE'' then old.cart_item_id else new.cart_item_id end;\n  perform pg_advisory_xact_lock(hashtextextended(v_line_id::text, 0));\n\n  -- Atomic Admin source invalidation may retire stale delivered tracks. Current\n  -- shipped narration remains immutable; only old-source DELETE is permitted.\n  IF TG_OP=''DELETE'' AND EXISTS(SELECT 1 FROM public.order_line_voice v WHERE v.cart_item_id=OLD.cart_item_id\n    AND (v.voice_asset_id IS DISTINCT FROM OLD.source_asset_id OR v.revision IS DISTINCT FROM OLD.source_revision)) THEN RETURN OLD; END IF;\n  if exists (\n    select 1\n    from public.cart_items item\n    join public.orders purchase_order on purchase_order.order_id = item.order_id\n    where item.cart_item_id = v_line_id\n      and item.status::text = ''ordered''\n      and lower(coalesce(item.package_type::text, '''')) = ''supreme''\n      and purchase_order.order_status::text in (''shipped'', ''delivered'')\n  ) then\n    raise exception ''Signature Voice narration is immutable after shipment''\n      using errcode = ''55000'';\n  end if;\n\n  return case when tg_op = ''DELETE'' then old else new end;\nend;\n","after_md5":"05e41c477ff6bddc9003eff5db95a21a"},{"identity":"public.enqueue_expired_unbound_voice_assets(p_cutoff timestamp with time zone, p_limit integer)","before":{"oid":"91172","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":63,"identity":"public.enqueue_expired_unbound_voice_assets(p_cutoff timestamp with time zone, p_limit integer)","in_scope":true,"language":"plpgsql","lf_count":63,"body_bytes":1690,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"integer","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"708722d3582a825658294d81ad12c9da","definition_md5":"0e7005b37d6e29735a56aad31b5b356e","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},"body":"\ndeclare\n  v_deleted integer := 0;\nbegin\n  if p_cutoff is null or p_limit not between 1 and 200 then\n    raise exception ''voice_cleanup_input_invalid'' using errcode = ''22023'';\n  end if;\n\n  with candidates as (\n    select asset.asset_id\n    from public.user_assets asset\n    where asset.asset_type::text = ''voice_sample''\n      and asset.created_at < p_cutoff\n      AND NOT EXISTS(SELECT 1 FROM public.user_asset_cleanup_provenance p WHERE p.asset_id=asset.asset_id)\n      and nullif(btrim(asset.storage_path), '''') is not null\n      and not exists (\n        select 1\n        from public.creations creation\n        where creation.voice_asset_id = asset.asset_id\n        UNION ALL SELECT 1 FROM public.order_line_voice line WHERE line.voice_asset_id=asset.asset_id\n      )\n    order by asset.created_at, asset.asset_id\n    for update of asset skip locked\n    limit p_limit\n  ), queued as (\n    insert into public.user_asset_cleanup_outbox (\n      asset_id,\n      asset_type,\n      bucket_name,\n      storage_path,\n      reason,\n      cleanup_status,\n      processing_token,\n      claimed_at,\n      next_attempt_at,\n      updated_at\n    )\n    select\n      asset.asset_id,\n      asset.asset_type::text,\n      ''raw-private'',\n      asset.storage_path,\n      ''orphan_expiry'',\n      ''pending'',\n      null,\n      null,\n      now(),\n      now()\n    from public.user_assets asset\n    join candidates candidate on candidate.asset_id = asset.asset_id\n    on conflict (bucket_name, storage_path) do update\n    set cleanup_status = ''pending'',\n        processing_token = null,\n        claimed_at = null,\n        next_attempt_at = now(),\n        updated_at = now()\n    returning asset_id\n  )\n  delete from public.user_assets asset\n  using queued\n  where asset.asset_id = queued.asset_id;\n\n  get diagnostics v_deleted = row_count;\n  return v_deleted;\nend;\n","after_md5":"8d5fce716f55bb0a56484b1ef31659ca"},{"identity":"public.delete_owned_unbound_user_asset(p_asset_id uuid, p_owner_type text, p_anon_session_id uuid, p_customer_id uuid)","before":{"oid":"91165","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":73,"identity":"public.delete_owned_unbound_user_asset(p_asset_id uuid, p_owner_type text, p_anon_session_id uuid, p_customer_id uuid)","in_scope":true,"language":"plpgsql","lf_count":73,"body_bytes":2165,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"06c3c8bf256f65860b67f63646afdcf1","definition_md5":"8f683f1c2ea7793c41eaeb33437d0218","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},"body":"\ndeclare\n  v_asset public.user_assets%rowtype;\n  v_cleanup_id uuid;\nbegin\n  if p_owner_type not in (''anon'', ''customer'') then\n    raise exception ''user_asset_owner_invalid'' using errcode = ''22023'';\n  end if;\n  if p_owner_type = ''anon'' and (p_anon_session_id is null or p_customer_id is not null) then\n    raise exception ''user_asset_owner_invalid'' using errcode = ''22023'';\n  end if;\n  if p_owner_type = ''customer'' and (p_customer_id is null or p_anon_session_id is not null) then\n    raise exception ''user_asset_owner_invalid'' using errcode = ''22023'';\n  end if;\n\n  select asset.*\n  into v_asset\n  from public.user_assets asset\n  where asset.asset_id = p_asset_id\n  for update;\n\n  if not found then\n    raise exception ''user_asset_not_found'' using errcode = ''P0002'';\n  end if;\n\n  if v_asset.owner_type::text <> p_owner_type\n    or v_asset.anon_session_id is distinct from p_anon_session_id\n    or v_asset.customer_id is distinct from p_customer_id then\n    raise exception ''user_asset_owner_mismatch'' using errcode = ''42501'';\n  end if;\n\n  if exists (\n    select 1\n    from public.creations creation\n    where creation.voice_asset_id = p_asset_id\n    UNION ALL SELECT 1 FROM public.user_asset_cleanup_provenance p WHERE p.asset_id=p_asset_id\n    UNION ALL SELECT 1 FROM public.order_line_voice line WHERE line.voice_asset_id=p_asset_id\n  ) then\n    raise exception ''voice_asset_bound'' using errcode = ''23503'';\n  end if;\n\n  if nullif(btrim(v_asset.storage_path), '''') is not null then\n    insert into public.user_asset_cleanup_outbox (\n      asset_id,\n      asset_type,\n      bucket_name,\n      storage_path,\n      reason,\n      cleanup_status,\n      next_attempt_at,\n      updated_at\n    )\n    values (\n      v_asset.asset_id,\n      v_asset.asset_type::text,\n      ''raw-private'',\n      v_asset.storage_path,\n      ''owner_delete'',\n      ''pending'',\n      now(),\n      now()\n    )\n    on conflict (bucket_name, storage_path) do update\n    set cleanup_status = ''pending'',\n        next_attempt_at = now(),\n        updated_at = now()\n    returning public.user_asset_cleanup_outbox.cleanup_id into v_cleanup_id;\n  end if;\n\n  delete from public.user_assets asset\n  where asset.asset_id = v_asset.asset_id;\n\n  return query\n  select v_cleanup_id, ''raw-private''::text, v_asset.storage_path;\nend;\n","after_md5":"87e16c9815c1c210990b37eb3fb645d0"},{"identity":"public.claim_user_asset_cleanup(p_limit integer)","before":{"oid":"91173","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":33,"identity":"public.claim_user_asset_cleanup(p_limit integer)","in_scope":true,"language":"plpgsql","lf_count":33,"body_bytes":987,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"cc583d1f7e061a5ef21b46a4f2217578","definition_md5":"8fa22b45c95cae7949cf9d09061209d4","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},"body":"\nDECLARE q public.user_asset_cleanup_outbox%rowtype; token uuid;\nBEGIN\n  IF p_limit NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION ''voice_cleanup_input_invalid'' USING ERRCODE=''22023''; END IF;\n  FOR q IN SELECT cleanup.* FROM public.user_asset_cleanup_outbox cleanup\n    WHERE ((cleanup.cleanup_status=''pending'' AND cleanup.next_attempt_at<=now())\n      OR (cleanup.cleanup_status=''processing'' AND cleanup.claimed_at<now()-interval ''15 minutes''))\n      AND NOT EXISTS(SELECT 1 FROM public.order_line_voice v JOIN public.user_assets a ON a.asset_id=v.voice_asset_id\n        WHERE cleanup.bucket_name=''raw-private'' AND a.storage_path=cleanup.storage_path)\n    ORDER BY cleanup.created_at,cleanup.cleanup_id FOR UPDATE SKIP LOCKED LIMIT p_limit\n  LOOP\n    -- Match the binder''s asset lock; the following statement sees committed references after waiting.\n    PERFORM 1 FROM public.user_assets a WHERE q.bucket_name=''raw-private''\n      AND (a.asset_id=q.asset_id OR a.storage_path=q.storage_path) ORDER BY a.asset_id FOR UPDATE;\n    IF q.bucket_name=''raw-private'' AND EXISTS(SELECT 1 FROM public.user_assets a\n      WHERE a.storage_path=q.storage_path AND\n        (EXISTS(SELECT 1 FROM public.order_line_voice v WHERE v.voice_asset_id=a.asset_id)\n          OR EXISTS(SELECT 1 FROM public.creations c WHERE c.voice_asset_id=a.asset_id))) THEN CONTINUE; END IF;\n    -- Fresh checks AFTER asset lock wait; do not use audit JSON as provenance.\n    IF EXISTS(SELECT 1 FROM public.user_asset_cleanup_provenance p WHERE p.bucket_name=q.bucket_name\n      AND p.storage_path=q.storage_path AND p.retained_after_shipment) THEN CONTINUE; END IF;\n    IF EXISTS(SELECT 1 FROM public.support_questions s WHERE s.closed_at IS NULL\n      AND (s.order_id=q.order_id OR s.order_id IN (SELECT p.order_id FROM public.user_asset_cleanup_provenance p\n        WHERE p.bucket_name=q.bucket_name AND p.storage_path=q.storage_path))) THEN\n      UPDATE public.user_asset_cleanup_outbox SET cleanup_status=''pending'',processing_token=NULL,claimed_at=NULL,\n        next_attempt_at=greatest(next_attempt_at,clock_timestamp()+interval ''1 hour''),updated_at=clock_timestamp()\n        WHERE cleanup_id=q.cleanup_id;\n      CONTINUE;\n    END IF;\n    -- Enqueued shared assets kept metadata until unbound. Removing the locked\n    -- metadata row now prevents a later Creation rebind during external deletion.\n    IF q.asset_type=''voice_sample'' AND EXISTS(SELECT 1 FROM public.user_asset_cleanup_provenance p\n      WHERE p.bucket_name=q.bucket_name AND p.storage_path=q.storage_path) THEN\n      DELETE FROM public.user_assets WHERE asset_id=q.asset_id AND storage_path=q.storage_path;\n    END IF;\n    token:=gen_random_uuid();\n    UPDATE public.user_asset_cleanup_outbox SET cleanup_status=''processing'',processing_token=token,\n      claimed_at=now(),updated_at=now() WHERE cleanup_id=q.cleanup_id;\n    RETURN QUERY SELECT q.cleanup_id,q.bucket_name,q.storage_path,token;\n  END LOOP;\nEND\n","after_md5":"9af93fa9d4bda8625281757da27ef1ae"}],"core":"-- S2: bounded provenance and retention state for the existing cleanup queue.\nALTER TABLE public.user_asset_cleanup_outbox ADD COLUMN order_id uuid REFERENCES public.orders(order_id) ON DELETE RESTRICT;\nALTER TABLE public.user_asset_cleanup_outbox ADD COLUMN cart_item_id uuid REFERENCES public.cart_items(cart_item_id) ON DELETE RESTRICT;\nALTER TABLE public.user_asset_cleanup_outbox DROP CONSTRAINT user_asset_cleanup_outbox_reason_check;\nALTER TABLE public.user_asset_cleanup_outbox ADD CONSTRAINT user_asset_cleanup_outbox_reason_check\n  CHECK(reason IN (''owner_delete'',''orphan_expiry'',''admin_replacement'',''customer_replacement''));\n-- A unique queue path can have several superseding orders. Also retains shipped\n-- files with NO queue entry; this is not a delivered-retention executor.\nCREATE TABLE public.user_asset_cleanup_provenance (\n  bucket_name text NOT NULL CHECK(bucket_name=''raw-private''),\n  storage_path text NOT NULL,\n  asset_id uuid NOT NULL,\n  asset_type text NOT NULL,\n  order_id uuid NOT NULL REFERENCES public.orders(order_id) ON DELETE RESTRICT,\n  cart_item_id uuid NOT NULL REFERENCES public.cart_items(cart_item_id) ON DELETE RESTRICT,\n  superseded_at timestamptz NOT NULL,\n  retained_after_shipment boolean NOT NULL,\n  PRIMARY KEY(bucket_name,storage_path,order_id,cart_item_id)\n);\nALTER TABLE public.user_asset_cleanup_provenance ENABLE ROW LEVEL SECURITY;\nREVOKE ALL ON public.user_asset_cleanup_provenance FROM PUBLIC,anon,authenticated,service_role;\nGRANT SELECT ON public.user_asset_cleanup_provenance TO service_role;\nCREATE INDEX user_asset_cleanup_provenance_asset_idx ON public.user_asset_cleanup_provenance(asset_id);\nCREATE INDEX user_asset_cleanup_provenance_order_idx ON public.user_asset_cleanup_provenance(order_id);\n\nCREATE FUNCTION public.enqueue_voice_superseded_file(p_order uuid,p_item uuid,p_asset uuid,p_type text,p_path text,p_reason text)\nRETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path='''' AS $$\nDECLARE shipped boolean; t timestamptz:=clock_timestamp();\nBEGIN\n  IF p_reason NOT IN (''admin_replacement'',''customer_replacement'') OR nullif(btrim(p_path),'''') IS NULL THEN\n    RAISE EXCEPTION ''voice_cleanup_provenance_invalid'' USING ERRCODE=''22023'';\n  END IF;\n  SELECT o.shipped_at IS NOT NULL INTO shipped FROM public.orders o JOIN public.cart_items i ON i.order_id=o.order_id\n    WHERE o.order_id=p_order AND i.cart_item_id=p_item;\n  IF NOT FOUND THEN RAISE EXCEPTION ''voice_cleanup_order_mismatch'' USING ERRCODE=''23514''; END IF;\n  INSERT INTO public.user_asset_cleanup_provenance(bucket_name,storage_path,asset_id,asset_type,order_id,cart_item_id,superseded_at,retained_after_shipment)\n  VALUES(''raw-private'',p_path,p_asset,p_type,p_order,p_item,t,shipped)\n  ON CONFLICT(bucket_name,storage_path,order_id,cart_item_id) DO UPDATE\n    SET superseded_at=greatest(public.user_asset_cleanup_provenance.superseded_at,excluded.superseded_at),\n      retained_after_shipment=public.user_asset_cleanup_provenance.retained_after_shipment OR excluded.retained_after_shipment;\n  IF shipped THEN RETURN false; END IF;\n  IF EXISTS(SELECT 1 FROM public.user_asset_cleanup_outbox WHERE bucket_name=''raw-private'' AND storage_path=p_path\n    AND cleanup_status=''processing'') THEN RAISE EXCEPTION ''voice_cleanup_in_flight'' USING ERRCODE=''PT409''; END IF;\n  INSERT INTO public.user_asset_cleanup_outbox(asset_id,asset_type,bucket_name,storage_path,reason,cleanup_status,next_attempt_at,updated_at,order_id,cart_item_id)\n  VALUES(p_asset,p_type,''raw-private'',p_path,p_reason,''pending'',t+interval ''30 days'',t,p_order,p_item)\n  ON CONFLICT(bucket_name,storage_path) DO UPDATE SET reason=excluded.reason,\n    cleanup_status=''pending'',processing_token=NULL,claimed_at=NULL,\n    next_attempt_at=greatest(public.user_asset_cleanup_outbox.next_attempt_at,excluded.next_attempt_at),updated_at=t,\n    order_id=coalesce(public.user_asset_cleanup_outbox.order_id,excluded.order_id),\n    cart_item_id=coalesce(public.user_asset_cleanup_outbox.cart_item_id,excluded.cart_item_id);\n  RETURN true;\nEND $$;\nREVOKE ALL ON FUNCTION public.enqueue_voice_superseded_file(uuid,uuid,uuid,text,text,text) FROM PUBLIC,anon,authenticated,service_role;\n\n-- A new signature, not a compatibility overload: S1-S3 deploy together.\nDROP FUNCTION public.materials_bind_voice(uuid,uuid,uuid,text,uuid,uuid);\nCREATE FUNCTION public.materials_bind_voice(p_order uuid,p_item uuid,p_customer uuid,p_hash text,\n  p_asset uuid,p_authorization uuid,p_expected_asset uuid,p_expected_revision integer)\nRETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='''' AS $$\nDECLARE o public.orders%rowtype; c public.order_line_voice%rowtype; a public.user_assets%rowtype;\n  v public.signature_voice_capture_authorizations%rowtype; old_asset public.user_assets%rowtype;\nBEGIN\n  SELECT * INTO o FROM public.orders WHERE order_id=p_order FOR UPDATE;\n  PERFORM public.materials_assert_access(p_order,p_customer,p_hash,p_item);\n  PERFORM pg_advisory_xact_lock(hashtextextended(p_item::text,0));\n  SELECT * INTO c FROM public.order_line_voice WHERE order_id=p_order AND cart_item_id=p_item FOR UPDATE;\n  IF NOT FOUND OR p_expected_revision IS NULL OR p_expected_revision<1\n    OR c.voice_asset_id IS DISTINCT FROM p_expected_asset OR c.revision IS DISTINCT FROM p_expected_revision THEN\n    RAISE EXCEPTION ''materials_voice_revision_conflict'' USING ERRCODE=''PT409''; END IF;\n  IF o.shipped_at IS NOT NULL THEN RAISE EXCEPTION ''materials_voice_shipped'' USING ERRCODE=''PT409''; END IF;\n  IF p_asset IS NULL OR p_asset IS NOT DISTINCT FROM c.voice_asset_id THEN\n    RAISE EXCEPTION ''materials_voice_new_asset_required'' USING ERRCODE=''22023''; END IF;\n  -- Stable asset lock order, including the old source, before deadline evaluation.\n  PERFORM 1 FROM public.user_assets WHERE asset_id IN (p_asset,c.voice_asset_id) ORDER BY asset_id FOR UPDATE;\n  SELECT * INTO a FROM public.user_assets WHERE asset_id=p_asset;\n  SELECT * INTO old_asset FROM public.user_assets WHERE asset_id=c.voice_asset_id;\n  SELECT * INTO v FROM public.signature_voice_capture_authorizations WHERE authorization_id=p_authorization FOR KEY SHARE;\n  IF a.asset_id IS NULL OR v.authorization_id IS NULL OR v.confirmed_at IS NULL OR v.confirmed_asset_id IS DISTINCT FROM p_asset\n    OR v.consent_version<>''signature-voice-consent-v3'' OR v.owner_type::text<>''customer''\n    OR v.customer_id IS DISTINCT FROM o.customer_id OR v.anon_session_id IS NOT NULL\n    OR a.owner_type::text<>''customer'' OR a.customer_id IS DISTINCT FROM o.customer_id OR a.anon_session_id IS NOT NULL THEN\n    RAISE EXCEPTION ''materials_voice_authorization_invalid'' USING ERRCODE=''23514''; END IF;\n  IF c.voice_asset_id IS NOT NULL AND clock_timestamp()>=o.paid_at+interval ''48 hours'' THEN\n    RAISE EXCEPTION ''materials_voice_window_closed'' USING ERRCODE=''PT409''; END IF;\n  UPDATE public.order_line_voice SET voice_asset_id=p_asset,voice_sample_duration_seconds=(a.metadata->>''duration_seconds'')::numeric,\n    voice_consent_version=v.consent_version,voice_consent_accepted_at=v.accepted_at,voice_bound_at=clock_timestamp(),\n    voice_subject_name=''Authorized narrator'',voice_subject_relationship=''authorized_submitter'',\n    voice_capture_authorization_id=p_authorization,voice_admin_authorization_id=NULL,voice_speaker_kind=v.speaker_kind,binding_origin=''post_payment''\n    WHERE cart_item_id=p_item RETURNING * INTO c;\n  IF old_asset.asset_id IS NOT NULL THEN\n    PERFORM public.enqueue_voice_superseded_file(p_order,p_item,old_asset.asset_id,''voice_sample'',old_asset.storage_path,''customer_replacement'');\n    INSERT INTO public.signature_voice_audit_events(order_id,cart_item_id,creation_id,source_asset_id,actor_customer_id,event_type,\n      reason,metadata) VALUES(p_order,p_item,c.creation_id,p_asset,o.customer_id,''source_replaced'',''Customer recording update'',\n      jsonb_build_object(''old_asset_id'',old_asset.asset_id,''new_asset_id'',p_asset,''source_revision'',c.revision,''actor_kind'',''customer''));\n  END IF;\n  RETURN jsonb_build_object(''asset_id'',c.voice_asset_id,''revision'',c.revision,''bound_at'',c.voice_bound_at);\nEND $$;\nREVOKE ALL ON FUNCTION public.materials_bind_voice(uuid,uuid,uuid,text,uuid,uuid,uuid,integer) FROM PUBLIC,anon,authenticated,service_role;\nGRANT EXECUTE ON FUNCTION public.materials_bind_voice(uuid,uuid,uuid,text,uuid,uuid,uuid,integer) TO service_role;\n\n-- True transaction-end fence: work/lock waits after the early check cannot\n-- commit a replacement past the deadline. Admin declarations and first capture exempt.\nCREATE FUNCTION public.enforce_customer_voice_commit_window() RETURNS trigger\nLANGUAGE plpgsql SECURITY DEFINER SET search_path='''' AS $$\nDECLARE o public.orders%rowtype;\nBEGIN\n  IF NEW.binding_origin=''post_payment'' AND NEW.voice_asset_id IS DISTINCT FROM OLD.voice_asset_id THEN\n    SELECT * INTO o FROM public.orders WHERE order_id=NEW.order_id;\n    IF o.shipped_at IS NOT NULL OR (OLD.voice_asset_id IS NOT NULL AND clock_timestamp()>=o.paid_at+interval ''48 hours'') THEN\n      RAISE EXCEPTION ''materials_voice_window_closed'' USING ERRCODE=''PT409''; END IF;\n  END IF;\n  RETURN NEW;\nEND $$;\nCREATE CONSTRAINT TRIGGER customer_voice_commit_window AFTER UPDATE ON public.order_line_voice\nDEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.enforce_customer_voice_commit_window();\nREVOKE ALL ON FUNCTION public.enforce_customer_voice_commit_window() FROM PUBLIC,anon,authenticated,service_role;\n","reason_check":{"name":"user_asset_cleanup_outbox_reason_check","type":"check","validated":true,"deferrable":false,"definition":"CHECK (reason = ANY (ARRAY[''owner_delete''::text, ''orphan_expiry''::text, ''admin_replacement''::text]))","child_schema":"public","parent_schema":null,"child_relation":"user_asset_cleanup_outbox","parent_relation":null,"initially_deferred":false},"after":[{"name":"materials_read","md5":"77de24e590776e6497a6ca09357e72f1","acl":"{postgres=X/postgres,service_role=X/postgres}","owner":"postgres","config_md5":"af3be9c3d4c2d891da1a7618c49685d3"},{"name":"materials_complete_grant","md5":"c8531db9bb8a45d7dd042a23cc8ae8d1","acl":"{postgres=X/postgres,service_role=X/postgres}","owner":"postgres","config_md5":"af3be9c3d4c2d891da1a7618c49685d3"},{"name":"replace_signature_voice_source","md5":"f1d96c9a88eae517377e9272baf0fb44","acl":"{postgres=X/postgres,service_role=X/postgres}","owner":"postgres","config_md5":"af3be9c3d4c2d891da1a7618c49685d3"},{"name":"invalidate_signature_voice_narration_on_source_change","md5":"ec8c723d8f7b1425a2643c316dedaeab","acl":"{postgres=X/postgres,service_role=X/postgres}","owner":"postgres","config_md5":"af3be9c3d4c2d891da1a7618c49685d3"},{"name":"lock_signature_voice_narration_creation","md5":"05e41c477ff6bddc9003eff5db95a21a","acl":"{postgres=X/postgres,service_role=X/postgres}","owner":"postgres","config_md5":"af3be9c3d4c2d891da1a7618c49685d3"},{"name":"enqueue_expired_unbound_voice_assets","md5":"8d5fce716f55bb0a56484b1ef31659ca","acl":"{postgres=X/postgres,service_role=X/postgres}","owner":"postgres","config_md5":"af3be9c3d4c2d891da1a7618c49685d3"},{"name":"delete_owned_unbound_user_asset","md5":"87e16c9815c1c210990b37eb3fb645d0","acl":"{postgres=X/postgres,service_role=X/postgres}","owner":"postgres","config_md5":"af3be9c3d4c2d891da1a7618c49685d3"},{"name":"claim_user_asset_cleanup","md5":"9af93fa9d4bda8625281757da27ef1ae","acl":"{postgres=X/postgres,service_role=X/postgres}","owner":"postgres","config_md5":"af3be9c3d4c2d891da1a7618c49685d3"},{"name":"enqueue_voice_superseded_file","md5":"3c72a8922d550b038303975568e6f7fa","acl":"{postgres=X/postgres}","owner":"postgres","config_md5":"af3be9c3d4c2d891da1a7618c49685d3"},{"name":"materials_bind_voice","md5":"9baf7d7dc5adbc1fc75f6fffe56fa727","acl":"{postgres=X/postgres,service_role=X/postgres}","owner":"postgres","config_md5":"af3be9c3d4c2d891da1a7618c49685d3"},{"name":"enforce_customer_voice_commit_window","md5":"0ab771988f3abf0fb88ff49fb4f44853","acl":"{postgres=X/postgres}","owner":"postgres","config_md5":"af3be9c3d4c2d891da1a7618c49685d3"}]}'::jsonb; r jsonb;p record;d text;old_acl text;old_rls boolean;
BEGIN
  IF current_user<>'postgres' THEN RAISE EXCEPTION 'voice_s2_operator_mismatch'; END IF;
  PERFORM set_config('lock_timeout','5s',true);
  LOCK TABLE public.orders,public.cart_items,public.order_line_voice,public.user_assets,public.user_asset_cleanup_outbox IN SHARE ROW EXCLUSIVE MODE;
  IF to_regclass('public.user_asset_cleanup_provenance') IS NOT NULL THEN RAISE EXCEPTION 'voice_s2_already_installed'; END IF;
  FOR r IN SELECT value FROM jsonb_array_elements(payload->'before') LOOP
    SELECT f.* INTO p FROM pg_proc f JOIN pg_namespace n ON n.oid=f.pronamespace
    WHERE format('%I.%I(%s)',n.nspname,f.proname,pg_get_function_identity_arguments(f.oid))=r->>'identity';
    IF p.oid IS NULL OR md5(p.prosrc) IS DISTINCT FROM r->>'raw_body_md5'
      OR pg_get_userbyid(p.proowner) IS DISTINCT FROM r->>'owner' OR p.proacl::text IS DISTINCT FROM r->>'raw_acl'
      OR p.prosecdef IS DISTINCT FROM (r->>'security_definer')::boolean
      OR md5(p.proconfig::text) IS DISTINCT FROM r->>'config_md5' THEN
      RAISE EXCEPTION 'voice_s2_source_drift:%',r->>'identity'; END IF;
  END LOOP;
  IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public.user_asset_cleanup_outbox'::regclass
    AND conname='user_asset_cleanup_outbox_reason_check' AND convalidated
    AND pg_get_constraintdef(oid,true)=payload#>>'{reason_check,definition}') THEN
    RAISE EXCEPTION 'voice_s2_reason_check_drift'; END IF;

  SELECT relacl::text,relrowsecurity INTO old_acl,old_rls FROM pg_class WHERE oid='public.user_asset_cleanup_outbox'::regclass;
  EXECUTE payload->>'core';
  FOR r IN SELECT value FROM jsonb_array_elements(payload->'patches') LOOP
    SELECT f.oid,f.prosrc,pg_get_functiondef(f.oid) AS definition INTO p FROM pg_proc f JOIN pg_namespace n ON n.oid=f.pronamespace
    WHERE format('%I.%I(%s)',n.nspname,f.proname,pg_get_function_identity_arguments(f.oid))=r->>'identity';
    EXECUTE replace(p.definition,p.prosrc,r->>'body');
    IF (SELECT md5(prosrc) FROM pg_proc WHERE oid=p.oid) IS DISTINCT FROM r->>'after_md5' THEN RAISE EXCEPTION 'voice_s2_after_hash'; END IF;
  END LOOP;
  IF EXISTS(SELECT 1 FROM pg_class WHERE oid='public.user_asset_cleanup_outbox'::regclass
    AND (relacl::text IS DISTINCT FROM old_acl OR relrowsecurity IS DISTINCT FROM old_rls)) THEN RAISE EXCEPTION 'voice_s2_queue_custody_drift'; END IF;
  FOR r IN SELECT value FROM jsonb_array_elements(payload->'after') LOOP
    SELECT f.* INTO p FROM pg_proc f JOIN pg_namespace n ON n.oid=f.pronamespace
    WHERE n.nspname='public' AND f.proname=r->>'name' AND md5(f.prosrc)=r->>'md5';
    IF p.oid IS NULL OR pg_get_userbyid(p.proowner) IS DISTINCT FROM r->>'owner'
      OR p.proacl::text IS DISTINCT FROM r->>'acl' OR NOT p.prosecdef
      OR md5(p.proconfig::text) IS DISTINCT FROM r->>'config_md5' THEN
      RAISE EXCEPTION 'voice_s2_after_custody:%',r->>'name'; END IF;
  END LOOP;
END $voice_s2$;
